                'sezioni' => [
                    ['titolo' => 'Trovare la pratica che ti serve', 'immagine' => 'stud_moduli.png', 'didascalia' => 'La modulistica: ogni pratica ha una breve spiegazione di cosa serve e a chi arriva.',
