                     'passi' => ['Apri il link ricevuto per email.', '<b>Istituzione scolastica:</b> denominazione, codice meccanografico, comune, indirizzo, codice fiscale, PEC e email della scuola.', '<b>Dirigente Scolastico:</b> nome, codice fiscale, luogo e data di nascita.', '<b>Attività dell’Allegato A:</b> per ogni attività prenotata indichi il numero di studenti e il docente tutor.', 'Premi il pulsante per preparare i documenti. Puoi tornare sulla stessa pagina dal link e correggere i dati: i documenti si aggiornano.']],
                    ['titolo' => 'Scaricare i documenti', 'immagine' => 'fsl_documenti_pronti.png', 'didascalia' => '«I documenti sono pronti»: l’Allegato A in PDF e la Convenzione in Word, con le istruzioni dei passi successivi.',
                     'passi' => ['Scarica l’<b>Allegato A (PDF)</b> e la <b>Convenzione (Word)</b>.', 'Controlla i dati. Eventuali correzioni si fanno nel Word; poi salva la Convenzione in PDF.'],
                     'nota' => 'Conserva la email con il link: serve per tornare sulla pagina e seguire la pratica.'],
                    ['titolo' => 'La firma del Dirigente', 'passi' => ['Il Dirigente firma la Convenzione in PDF <b>in formato PAdES</b> (un PDF firmato). Il formato CAdES (file .p7m) non è accettato.', 'Dopo la firma il file non va più modificato né salvato di nuovo: il portale controlla che la firma sia integra.', 'L’Allegato A si carica in PDF, anche senza firma digitale.', 'In alternativa al caricamento si può inviare tutto dalla PEC della scuola alla PEC del Dipartimento (dipartimento.best@pec.unical.it).']],
                    ['titolo' => 'Caricare la convenzione firmata', 'immagine' => 'fsl_firmata_caricata.png', 'didascalia' => 'Il riquadro «Convenzione firmata» conferma la ricezione, con data e firmatario.',
                     'passi' => ['Nella stessa pagina scegli il PDF firmato e l’Allegato A e premi il pulsante di caricamento.', 'Compare la conferma di ricezione e ti arriva la email «Convenzione ricevuta».', 'Se hai sbagliato file puoi sostituirlo con uno nuovo finché il Dipartimento non lo ha preso in carico.']],
                    ['titolo' => 'Che cosa fa il Dipartimento', 'immagine' => 'fsl_presa_in_carico.png', 'didascalia' => 'Il Dipartimento ha preso in carico la convenzione: la pagina mostra il protocollo in entrata.',
                     'passi' => ['<b>Presa in carico:</b> l’ufficio registra il protocollo in entrata e ti scrive (email «Convenzione presa in carico»).', '<b>Firma del Direttore:</b> la convenzione va al Direttore, che firma in PAdES. Tu non devi fare nulla.', '<b>Protocollo definitivo:</b> l’ufficio registra il protocollo e la validità: la convenzione diventa attiva e le prenotazioni in attesa si confermano.', 'Se c’è un problema l’ufficio <b>rifiuta il file con un motivo</b>: ricevi l’email «Convenzione da correggere», correggi e carichi di nuovo il file.']],
                    ['titolo' => 'La convenzione è attiva', 'immagine' => 'fsl_attiva.png', 'didascalia' => 'La pagina conferma che la convenzione è firmata dal Direttore e protocollata.',
                     'passi' => ['Ricevi l’email «Convenzione attiva».', 'Le prenotazioni in attesa della scuola sono confermate.']],
                    ['titolo' => 'Dove ritrovarla', 'immagine' => 'fsl_area_attiva.png', 'didascalia' => 'Area personale, scheda «Programma FSL»: la convenzione in vigore, con protocollo e validità, e i documenti da scaricare.',
                     'passi' => ['Tutti i docenti collegati alla scuola vedono e scaricano la convenzione firmata e l’Allegato A dalla scheda «Programma FSL» dell’Area personale.', 'La convenzione vale <b>un anno</b>. Poco prima della scadenza il Dipartimento avvisa e si rifà lo stesso percorso con una nuova convenzione; le scadute restano consultabili.']],
                ],
            ],
            'elenco' => [
                'titolo' => 'Docenti delle scuole: l’elenco degli studenti FSL', 'icona' => 'fa-list-ol', 'colore' => '#0f766e',
                'a_chi' => 'Per il docente che ha prenotato un’attività di Formazione Scuola Lavoro per la sua classe e deve consegnare l’elenco dei partecipanti.',
                'in_breve' => 'Dopo la prenotazione, e prima dell’attività, consegni due cose dalla tua Area personale: l’elenco degli studenti (cognome e nome) e l’autorizzazione della scuola in PDF. Con quei nomi il portale prepara gli attestati di partecipazione.',
                'sezioni' => [
                    ['titolo' => 'Aprire la pagina dell’elenco', 'immagine' => 'fsl_elenco_1_area.png', 'didascalia' => 'Area personale, «Prossimi eventi»: sotto la prenotazione c’è il pulsante «Carica elenco e autorizzazione», con la data entro cui consegnare.',
                     'passi' => ['Accedi al portale e apri la tua Area personale.', 'Nella prenotazione dell’attività premi <b>«Carica elenco e autorizzazione»</b>. Accanto vedi la scadenza («entro il …»).', 'Il pulsante è disponibile anche se la convenzione della scuola non è ancora attiva.'],
                     'nota' => 'Se la scadenza si avvicina e manca qualcosa, il portale ti manda promemoria periodici e un ultimo avviso.'],
                    ['titolo' => 'La pagina dei documenti', 'immagine' => 'fsl_elenco_2_pagina.png', 'didascalia' => 'In alto i documenti ancora da consegnare (studenti inseriti e autorizzazione); sotto, a sinistra l’elenco a mano, a destra l’autorizzazione e il modello Excel.',
                     'passi' => ['In alto un riepilogo: quanti studenti hai inserito sul totale iscritto («0 / 15 studenti»), se manca l’autorizzazione e la data entro cui consegnare.', 'Quando tutto è completo compare «Documenti completi».']],
                    ['titolo' => 'Inserire i nomi a mano', 'immagine' => 'fsl_elenco_4_compilato.png', 'didascalia' => 'Una riga per studente: cognome e nome. In fondo il conteggio e «Salva l’elenco».',
                     'passi' => ['Scrivi <b>cognome</b> e <b>nome</b> di ogni studente, una riga per studente.', 'Servono altre righe? Premi «Aggiungi studente». Per toglierne una usa la X rossa.', 'Hai l’elenco in Excel? Seleziona le due colonne, copia e incolla nella prima casella libera: le righe si riempiono da sole.', 'Premi <b>«Salva l’elenco»</b>. Puoi tornare e correggerlo quando vuoi.'],
                     'nota' => 'Ogni studente deve avere cognome e nome. Non puoi inserire più studenti di quelli indicati nell’iscrizione: per aumentare il numero chiedi alla segreteria.'],
                    ['titolo' => 'Oppure usare il modello Excel', 'immagine' => 'fsl_elenco_3_excel.png', 'didascalia' => 'Riquadro «Usa il modello Excel»: scarica, compila, carica.',
                     'passi' => ['Premi <b>«Scarica il modello»</b> e compila le colonne Cognome e Nome.', 'Salva il file e caricalo con <b>«Carica e sostituisci»</b> (file .xlsx o .csv).', 'Il file <b>sostituisce</b> l’elenco attuale: il portale te lo chiede prima di procedere.']],
                    ['titolo' => 'Controllare che sia salvato', 'immagine' => 'fsl_elenco_5_salvato.png', 'didascalia' => 'Dopo il salvataggio il riepilogo mostra «5 / 15 studenti» e i nomi restano nelle righe.',
                     'passi' => ['Il contatore in alto si aggiorna (qui «5 / 15 studenti»).', 'Se ti manca ancora qualche nome puoi aggiungerlo più tardi, finché non sono stati inviati gli attestati.']],
                    ['titolo' => 'L’autorizzazione della scuola', 'passi' => ['Nel riquadro «Autorizzazione della scuola» scegli il PDF (al massimo 10 MB) e premi <b>«Carica l’autorizzazione»</b>.', 'Puoi aprirla per controllarla, sostituirla con un altro PDF o toglierla.', 'A elenco e autorizzazione consegnati compare «Documenti completi».']],
                    ['titolo' => 'Dopo l’attività: gli attestati', 'passi' => ['I nomi servono a generare gli attestati di partecipazione, che partono dopo l’attività (per le classi con presenza registrata).', 'Dopo l’invio degli attestati l’elenco non è più modificabile dal docente: per correggere un nome scrivi alla segreteria.']],
                ],
            ],
            'tutor' => [
                'titolo' => 'Tutor', 'icona' => 'fa-user-pen', 'colore' => '#b45309',
                'a_chi' => 'Per chi ha vinto un bando di tutorato: lettera d’incarico, registro delle attività e compenso.',
                'in_breve' => 'Confermi l’incarico con SPID o CIE, indichi i dati per il pagamento, registri le attività svolte e, a fine attività, il docente firma la dichiarazione e l’ufficio pagamenti procede.',
                'sezioni' => [
                    ['titolo' => 'L’incarico', 'immagine' => 'tutorato_1_dati_pagamento.png', 'didascalia' => 'Dati per il pagamento nella dichiarazione individuale.',
                     'passi' => ['Ricevi una email con il link alla lettera d’incarico: apri, controlla e conferma con SPID o CIE (livello 2).', 'Compili online la dichiarazione individuale: l’IBAN viene conservato cifrato.', 'La lettera è firmata dal docente e dal Direttore: ricevi il documento firmato e il protocollo.']],
                    ['titolo' => 'Registro e fine attività', 'immagine' => 'tutorato_7_area_personale.png', 'didascalia' => 'L’Area personale del tutor.',
                     'passi' => ['Nel registro scrivi le attività svolte, con data e ore. Il compenso in lettera lo calcola il portale (ore × 25 euro lordi per l’ente, diviso 1,24); se fai meno ore viene ricalcolato.', 'A fine attività richiedi la dichiarazione di fine attività: il docente titolare approva le ore e la firma, poi il referente del tutorato controlla ore e compenso e passa la pratica ai pagamenti.', 'L’ufficio pagamenti riceve la pratica e registra il pagamento: vedi lo stato dalla tua Area personale.']],
                ],
            ],
            'azienda' => [
                'titolo' => 'Enti e aziende: la convenzione per la tesi', 'icona' => 'fa-handshake', 'colore' => '#047857',
                'a_chi' => 'Per gli enti e le aziende che accolgono studenti del Dipartimento per la tesi e devono stipulare la convenzione: legali rappresentanti, uffici del personale e referenti.',
                'in_breve' => 'Non serve registrarsi. Chiedi la convenzione con la tua email, ricevi un link personale, inserisci i dati dell’azienda, scarichi la convenzione già compilata, la firmi digitalmente (PAdES) e la ricarichi. Al resto pensa il Dipartimento: protocollo, firma del Direttore e archivio. Se vuoi cambiare qualche articolo puoi proporlo nella stessa pagina.',
                'sezioni' => [
                    ['titolo' => 'Chiedere la convenzione', 'immagine' => 'tesi_5_richiesta_pubblica.png', 'didascalia' => 'La pagina pubblica per chiedere la convenzione: nome dell’ente, email e una domanda di controllo.',
                     'passi' => ['Apri la pagina «Convenzione di tesi per enti e aziende» (dal sito del Dipartimento, menu Studenti → Tesi) oppure l’indirizzo che ti ha dato il Dipartimento.', 'Scrivi il nome dell’ente o dell’azienda e un’email (meglio quella dell’ufficio che segue la pratica), rispondi alla domanda di controllo e premi «Inviami il link».', 'Se il Dipartimento ti ha già invitato, il link è nella email che hai ricevuto: salta questo passaggio.'],
                     'nota' => 'Il link è personale: puoi chiudere la pagina e riprendere più tardi dallo stesso link. Se lo perdi, richiedilo di nuovo con la stessa email: ricevi il link della convenzione già aperta.'],
                    ['titolo' => 'Inserire i dati', 'immagine' => 'tesi_2_azienda_modulo.png', 'didascalia' => 'La pagina della convenzione: dati dell’azienda, rappresentante legale e, sotto, gli articoli.',
                     'passi' => ['<b>Dati dell’ente:</b> ragione sociale, partita IVA o codice fiscale, sede legale, PEC; facoltativi settore e sito.', '<b>Rappresentante legale:</b> nome e cognome e la qualifica (per esempio Amministratore Unico): è la persona che firma.', '<b>Elenco pubblico:</b> se spunti il consenso, l’azienda compare nell’elenco delle aziende convenzionate sul sito del Dipartimento (nome, comune, settore e sito).', 'Premi «Salva e continua».']],
                    ['titolo' => 'Se vuoi cambiare un articolo', 'passi' => ['Il testo è quello standard del Dipartimento. Apri l’articolo che ti interessa, scegli «Proponi una modifica» e scrivi il testo come lo vorresti.', 'Dopo il salvataggio la convenzione resta ferma: il Dipartimento valuta la proposta e ti scrive. Non puoi firmare finché non risponde.', 'Il Dipartimento può <b>accettare</b>, <b>rifiutare</b> (con la spiegazione) o <b>rispondere con un altro testo</b>. In quest’ultimo caso puoi accettarlo, ritirare la tua modifica o scriverne una nuova.', 'Quando tutte le modifiche sono decise ricevi una email e puoi scaricare la convenzione.'],
                     'nota' => 'Le modifiche concordate compaiono nel PDF e nel Word che scarichi: non devi correggere nulla a mano.'],
                    ['titolo' => 'Scaricare, firmare e ricaricare', 'passi' => ['Premi «Scarica il PDF da firmare» (è anche disponibile il Word). Controlla i dati: se qualcosa non va correggi nella pagina e riscarica.', 'Il legale rappresentante firma il <b>PDF</b> con la <b>firma digitale in formato PAdES</b> (un PDF firmato). Il formato CAdES (file .p7m) non è accettato.', 'Carica il PDF firmato nel riquadro «Firma e ricarica». <b>Dopo la firma il file non va più modificato né salvato di nuovo</b>: il portale controlla che la firma sia integra.', 'Ricevi subito la conferma di ricezione. Se hai sbagliato file puoi sostituirlo finché il Dipartimento non lo ha preso in carico.']],
                    ['titolo' => 'Che cosa fa il Dipartimento e la convenzione stipulata', 'immagine' => 'tesi_4_elenco_pubblico.png', 'didascalia' => 'L’elenco pubblico delle aziende convenzionate per la tesi.',
                     'passi' => ['<b>Presa in carico:</b> l’ufficio protocolla la convenzione e ti scrive. Poi la fa firmare al Direttore: tu non devi fare nulla.', '<b>Se c’è un problema</b> l’ufficio rifiuta il file con un motivo: ricevi la email, correggi e carichi di nuovo.', '<b>Convenzione stipulata:</b> ricevi una email con il protocollo e le date di validità e dalla stessa pagina scarichi la convenzione firmata. Vale <b>cinque anni</b> (art. 10).', 'Se hai dato il consenso, l’azienda compare nell’elenco pubblico delle aziende convenzionate.']],
                    ['titolo' => 'Rinnovare la convenzione', 'passi' => ['Circa due mesi prima della scadenza ricevi una email con il link della convenzione.', 'Dalla pagina premi «Rinnova la convenzione»: i dati sono già inseriti, controllali, scarica e firma la nuova convenzione come la prima volta.']],
                ],
            ],
            'convenzioni_tesi' => [
                'titolo' => 'Ufficio: le convenzioni di tesi', 'icona' => 'fa-file-signature', 'colore' => '#047857',
                'a_chi' => 'Per le persone dell’«Ufficio convenzioni di tesi» (Gestione del portale → Uffici), che invitano le aziende, valutano le modifiche agli articoli e protocollano.',
                'in_breve' => 'Didattica → «Convenzioni di tesi» mostra l’iter in sei passi e, per ogni convenzione, solo ciò che tocca a te: valutare le modifiche agli articoli, protocollare in entrata (il Direttore riceve da solo il link) e protocollare in uscita con la validità. Nell’archivio trovi tutte le convenzioni, anche quelle già in essere.',
                'sezioni' => [
                    ['titolo' => 'Avviare una convenzione', 'immagine' => 'tesi_1_pannello_da_seguire.png', 'didascalia' => 'Il pannello «Da seguire»: i sei passi, chi li fa e le convenzioni che aspettano l’ufficio.',
                     'passi' => ['Da Didattica apri «Convenzioni di tesi». In cima ci sono i sei passi dell’iter con il numero di convenzioni in ciascuno.', 'Per invitare un’azienda scrivi l’email (e il nome, se vuoi) in «Invita un’azienda» e premi «Invia il link»: l’azienda riceve il link per compilare.', 'Oppure dai all’azienda l’indirizzo della pagina pubblica (lo trovi nel riquadro «Pagina per le aziende»): si richiede da sola.']],
                    ['titolo' => 'Valutare le modifiche agli articoli', 'passi' => ['Se l’azienda propone modifiche la convenzione compare in «Modifiche agli articoli da valutare», con il testo standard e la proposta affiancati.', 'Per ogni articolo scegli <b>Accetto</b>, <b>Rifiuto</b> (scrivi sempre il motivo) oppure <b>Rispondo con un altro testo</b> e riscrivilo.', 'Premi «Manda la risposta all’azienda»: la convenzione torna all’azienda, che può firmare solo quando tutte le modifiche sono decise.'],
                     'nota' => 'Per una modifica importante conviene sentire il Direttore prima di accettare: il testo concordato finisce nel documento che l’azienda firma.'],
                    ['titolo' => 'Protocollo in entrata', 'passi' => ['Quando l’azienda carica il PDF firmato compare in «Firmate dalle aziende: da prendere in carico» e ricevi una email.', 'Scarica il PDF, protocollalo nel sistema di Ateneo e scrivi qui numero e data del protocollo in entrata.', 'Premi «Registra e manda al Direttore»: l’azienda riceve l’avviso e il Direttore (o il vice, se è attivo «Direttore assente») riceve l’email con il link per firmare. Non devi ricaricare nulla.', 'Se qualcosa non va, «Rifiuta con un motivo»: l’azienda riceve la spiegazione e ricarica il file.']],
                    ['titolo' => 'La firma del Direttore', 'immagine' => 'tesi_6_direttore_firma.png', 'didascalia' => 'La pagina di firma del Direttore: il PDF dell’azienda e la firma in PAdES.',
                     'passi' => ['Il Direttore firma dal suo link (firma remota oppure scarica, firma e ricarica). Il portale controlla che il PDF sia quello dell’azienda con una firma in più.', 'Se l’email non è partita (per esempio perché il Direttore non è indicato) la convenzione resta «da mandare al Direttore»: controlla la Direzione in Gestione del portale → Uffici e premi «Invia al Direttore».', 'Puoi rimandare il link con «Rimanda il link».']],
                    ['titolo' => 'Protocollo in uscita: convenzione stipulata', 'passi' => ['Quando il Direttore firma la convenzione passa a «Firmate dal Direttore: protocollo in uscita» e ricevi una email.', 'Scarica il PDF firmato, protocollalo e scrivi numero, data e <b>validità</b> (di partenza cinque anni, come dice l’art. 10). Se vuoi carica anche il PDF con la segnatura di protocollo.', 'Premi «Registra: convenzione stipulata»: va in archivio, l’azienda riceve l’avviso e, se ha dato il consenso, compare nell’elenco pubblico.']],
                    ['titolo' => 'Archivio, convenzioni già in essere e rinnovi', 'immagine' => 'tesi_3_archivio.png', 'didascalia' => 'L’archivio: ricerca, filtri valide/scadute, inserimento a mano, rinnovo.',
                     'passi' => ['In «Archivio e aziende convenzionate» cerchi per azienda, protocollo o comune e filtri valide o scadute.', 'Per le convenzioni stipulate prima del portale usa «Inserisci una convenzione già in essere»: ragione sociale, protocollo e validità bastano; il PDF è facoltativo. Con il consenso l’azienda compare nell’elenco pubblico.', 'Due mesi prima della scadenza l’azienda e l’ufficio ricevono un avviso. Con «Rinnova» l’azienda riceve il link con i dati già inseriti.', 'Le aziende ferme da una settimana ricevono un promemoria; dall’elenco «In corso con l’azienda» puoi anche rimandare il link a mano.']],
                ],
            ],
            'direttore' => [
                'titolo' => 'Direttore', 'icona' => 'fa-gauge-high', 'colore' => '#0f2a4a',
                'a_chi' => 'Per il Direttore del Dipartimento: cose da firmare e cose che si sono fermate.',
                'in_breve' => 'Il cruscotto riunisce in una pagina ciò che aspetta la tua firma e ciò che si è fermato nei vari moduli. Non cambia nulla: serve a vedere dove intervenire. Le firme si fanno dal link personale.',
                'sezioni' => [
                    ['titolo' => 'Il cruscotto', 'immagine' => 'dir_cruscotto.png', 'didascalia' => 'Nove gruppi: firme, pratiche ferme, conferme in ritardo, verbali, convenzioni, tutorato, risorse.',
                     'passi' => ['Dall’Area personale premi «Cruscotto del Direttore»: in alto vedi quante cose da guardare ci sono.', 'Ogni gruppo ha il suo numero. Le righe con i giorni in rosso aspettano da sette giorni o più.', 'Premi su una riga per andare direttamente alla pratica, al documento da firmare o alla pagina del modulo.', 'Gruppi: documenti da firmare, convenzioni FSL da firmare, pratiche ferme, conferme dei docenti in ritardo, verbali in attesa di firma, convenzioni in scadenza, pagamenti del tutorato fermi, scadenze delle risorse, prenotazioni da approvare ferme.']],
                    ['titolo' => 'Firmare', 'immagine' => 'dir_firma.png', 'didascalia' => 'La pagina di firma: accedi, controlla il PDF, firma in PAdES.',
                     'passi' => ['Per certificati, attestati, convenzioni e lettere ricevi una email con il link personale (lo trovi anche nel cruscotto).', 'Accedi con le tue credenziali: solo tu puoi aprire il tuo link. Vedi il PDF accanto e firmi con la firma remota oppure scarichi, firmi in PAdES e ricarichi.', 'Il portale controlla che il file sia firmato e che il firmatario corrisponda al codice fiscale indicato. Dopo la firma l’ufficio riceve l’avviso.'],
                     'nota' => 'Il Direttore e il vice direttore si scelgono dall’anagrafe di Ateneo nella Direzione (Gestione del portale → Uffici e persone): valgono per tutte le firme.'],
                    ['titolo' => 'Quando sei assente: il vice', 'passi' => ['Il vice direttore ha gli stessi permessi del Direttore (cruscotto e firme), ma i link di firma e gli avvisi arrivano a te finché non attivi l’interruttore.', 'Dall’Area personale apri la card <b>«Direttore assente»</b>, indica (se vuoi) la data di rientro e premi «Il Direttore è assente: passa al vice»: da quel momento firme, link e riepilogo vanno al vice.', 'Al ritorno premi «Il Direttore è tornato» (se hai indicato la data di rientro l’interruttore si spegne da solo). Lo possono attivare anche il vice e la segreteria di direzione.']],
                ],
            ],
            'assistenza' => [
                'titolo' => 'Assistenza e Didacticus', 'icona' => 'fa-headset', 'colore' => '#B30000',
                'a_chi' => 'Per le persone dell’ufficio «Assistenza» e per chi istruisce Didacticus, l’assistente virtuale del portale.',
                'in_breve' => 'Studenti, personale ed esterni scrivono dal pulsante «Serve aiuto?». Risponde prima Didacticus; quando non basta, la chat arriva a te con un avviso (email e, se vuoi, una finestrella di Windows). Rispondi nella chat, che si aggiorna da sola. Dal pannello insegni a Didacticus nuove risposte, con link e allegati, e vedi cosa non ha saputo dire.',
                'sezioni' => [
                    ['titolo' => 'Rispondere alle chat', 'immagine' => 'ass_coda.png', 'didascalia' => 'La casella: a sinistra le schede Da prendere · Mie · Tutte · Con Didacticus · Chiuse; a destra la chat aperta.',
                     'passi' => ['Apri <b>Didattica → Assistenza</b> (o la voce «Assistenza» nella Scrivania). Il numero sulla voce di menu e sulla scheda «Da prendere» dice quante persone aspettano.', 'Scegli una chat: vedi chi scrive (con accesso o esterno), l’argomento, la pratica collegata e tutta la conversazione, comprese le risposte di Didacticus.', 'Premi <b>«Prendo io»</b> o semplicemente rispondi: la chat passa a te e chi ha scritto lo vede («Ti risponde …»). Invio manda il messaggio, Maiusc+Invio va a capo.', '<b>«Passa a…»</b> gira la chat a un collega dell’ufficio, che riceve subito l’avviso. <b>«Chiudi»</b> la chiude; se la persona riscrive si riapre da sola.', 'Le <b>note interne</b> (spunta «Nota interna») le vedi solo tu e i colleghi: servono per passarsi informazioni. La persona non le vede.'],
                     'nota' => 'Le chat compaiono anche nella casella «Messaggi» in alto, insieme alle conversazioni sulle prenotazioni e sulle convenzioni FSL.'],
                    ['titolo' => 'Una chat in carico', 'immagine' => 'ass_chat.png', 'didascalia' => 'La domanda, la risposta di Didacticus (azzurra), la nota interna (gialla) e la tua risposta.',
                     'passi' => ['Quando una chat arriva da Didacticus trovi una nota che dice perché (la persona ha chiesto un operatore, la risposta non è bastata, non ha trovato risposte) e vedi cosa gli è già stato risposto: non ripeterlo.', 'Se la chat è fuori dagli orari, la persona ha già letto l’avviso con gli orari: rispondi appena puoi, le arriva per email.', 'Se la risposta che dai è una che serve spesso, aggiungila a Didacticus: vedi più sotto.'],
                     'nota' => 'La scheda «Con Didacticus» mostra le chat che sta ancora seguendo lui: puoi aprirle e, se serve, prenderle.'],
                    ['titolo' => 'Notifiche a finestrella su Windows', 'passi' => ['Nella pagina Assistenza premi <b>«Attiva le notifiche su questo computer»</b> e accetta il permesso del browser (Chrome o Edge). Poi premi «Prova»: deve comparire una finestrella.', 'Da quel momento una nuova richiesta o un messaggio nelle tue chat compare come finestrella, anche se la pagina è chiusa (il browser deve essere aperto, anche ridotto a icona). Un clic apre la chat giusta.', 'Puoi <b>silenziare</b> le notifiche per 1 ora, 4 ore o fino a domani, e scegliere <b>«Solo le chat in carico a me»</b> per non sentire le richieste da prendere.', 'Se la finestrella non compare controlla che Windows non sia in «Non disturbare» e che le notifiche di Chrome/Edge siano attive nelle Impostazioni di Windows.'],
                     'nota' => 'Se il portale non ha le chiavi per le notifiche, la barra lo dice e restano le email. Le notifiche non contengono mai dati che non servono a te.'],
                    ['titolo' => 'Orari e servizio', 'passi' => ['In fondo alla pagina Assistenza, «Orari e servizio»: scrivi per ogni giorno gli orari in cui rispondete, per esempio <code>09:00-13:00, 14:00-16:00</code>, e lascia vuoto un giorno senza assistenza.', 'Fuori orario la chat funziona lo stesso: chi scrive vede un avviso con gli orari e riceve la risposta per email. Senza nessun orario il servizio è considerato sempre aperto.', 'L’interruttore «Servizio acceso» spegne tutto: il pulsante «Serve aiuto?» sparisce dal sito e non si aprono nuove chat (quelle in corso restano).']],
                    ['titolo' => 'Statistiche', 'immagine' => 'ass_statistiche.png', 'didascalia' => 'Chat per argomento e per operatore, tempi e utilità, in un periodo a scelta.',
                     'passi' => ['La scheda «Statistiche» mostra quante chat sono arrivate, quante risolte da Didacticus e quante passate agli operatori, il tempo medio di prima risposta e quanti hanno trovato utile l’assistenza.', 'Le due tabelle (per argomento e per operatore) si scaricano con «Scarica» in Excel, PDF o CSV.', 'I numeri non contengono nomi né messaggi: restano anche dopo la cancellazione delle chat vecchie (12 mesi).']],
                    ['titolo' => 'Istruire Didacticus: le voci', 'immagine' => 'did_voci.png', 'didascalia' => 'La base di conoscenza: ogni voce è una risposta, con quante volte è stata usata e quanti l’hanno trovata utile.',
                     'passi' => ['Apri <b>Didattica → Didacticus</b>. Le <b>voci</b> sono tutto quello che sa: Didacticus risponde <b>solo</b> con quello che trovi qui e non inventa nulla.', 'Premi <b>«Nuova voce»</b> (o «Modifica» su una esistente). Con «Spegni» una voce resta salvata ma Didacticus non la usa; con il cestino la elimini.', 'Per scrivere tante voci in una volta: <b>Scarica → CSV</b>, aggiungi righe in Excel (Argomento, Titolo, Domande, Parole chiave, Risposta, Link, Attiva) e riportale con «Importa da CSV». Le voci con lo stesso titolo si aggiornano.']],
                    ['titolo' => 'Come si scrive una voce', 'immagine' => 'did_voce.png', 'didascalia' => 'Una voce: titolo, domande, parole chiave, risposta, link e allegati.',
                     'passi' => ['<b>Domande</b>: una per riga, come le scriverebbe uno studente («Come richiedo il certificato di iscrizione», «Ho bisogno di un certificato»). Più modi scrivi, meglio capisce.', '<b>Parole chiave e sinonimi</b>, separate da virgola: le parole che, se compaiono nella domanda, indicano questa voce («certificato, attestazione, marca da bollo»). Anche frasi di più parole.', '<b>Risposta</b>: scrivi come parleresti a uno studente. Riga vuota = nuovo paragrafo; righe che iniziano con «- » = elenco; <code>**testo**</code> = grassetto; gli indirizzi web diventano link. Non scrivere nomi di persone o dati personali.', '<b>Link</b>: diventano pulsanti sotto la risposta. Metti il testo del pulsante e l’indirizzo (https://… oppure una pagina del portale, per esempio <code>modulistica.php</code>).', '<b>Allegati</b>: moduli da scaricare (PDF, Word, Excel, immagini, fino a 10 MB). Chi chiede li scarica con un clic.', 'Le opzioni: <b>Attiva</b>; <b>Solo per chi ha fatto l’accesso</b> (gli esterni vengono invitati ad accedere); <b>Proponi sempre un operatore</b> per le risposte che spesso non bastano.'],
                     'nota' => 'Non scrivere importi, scadenze o regole che cambiano senza indicare dove trovarle: se cambiano, la voce resta sbagliata finché qualcuno non la corregge. Meglio un link alla fonte ufficiale.'],
                    ['titolo' => 'Provare Didacticus', 'immagine' => 'did_prova.png', 'didascalia' => 'La prova: cosa risponderebbe e le voci più vicine, con il punteggio.',
                     'passi' => ['Nella scheda <b>Prova</b> scrivi una domanda come la scriverebbe uno studente: vedi se Didacticus risponderebbe, proporrebbe delle voci («intendevi…?») o direbbe di non saper rispondere.', 'La tabella mostra le cinque voci più vicine con il punteggio e le parole che ha riconosciuto. Una risposta arriva solo se il punteggio supera la <b>soglia</b> (predefinita 60).', 'Se una domanda va male: aggiungi quella frase alle «Domande» della voce giusta, oppure una parola chiave o un sinonimo, e riprova.']],
                    ['titolo' => 'Imparare da quello che gli viene chiesto', 'immagine' => 'did_mancate.png', 'didascalia' => 'Le domande a cui Didacticus non ha saputo rispondere o la cui risposta non è bastata.',
                     'passi' => ['La scheda <b>«Domande senza risposta»</b> raccoglie le domande che Didacticus non ha saputo gestire e quelle in cui la persona ha detto «Non mi basta». Il numero rosso nel menu dice quante sono da vedere.', 'Premi <b>«Crea una voce»</b>: si apre una voce già con la domanda e, se un operatore aveva risposto a quella chat, con la sua risposta come bozza. Rivedila e salva: la prossima volta Didacticus saprà rispondere.', 'Con <b>«Metti da parte»</b> togli dall’elenco le domande che non servono (si possono rimettere in lista).'],
                     'nota' => 'Le domande si cancellano insieme alle chat dopo 12 mesi.'],
                    ['titolo' => 'Impostazioni e immagine di Didacticus', 'immagine' => 'did_impostazioni.png', 'didascalia' => 'Acceso/spento, saluto, soglia di sicurezza e immagine di profilo.',
                     'passi' => ['<b>Acceso/spento</b>: spento, le nuove chat vanno subito agli operatori come prima.', '<b>Saluto</b>: il primo messaggio di Didacticus (puoi cambiarlo).', '<b>Soglia di sicurezza</b>: più alta = più prudente (risponde meno e passa agli operatori più spesso); più bassa = risponde anche con domande vaghe ma può sbagliare voce. Si consiglia 60; provala con la scheda «Prova».', '<b>Immagine di profilo</b>: puoi caricare un’altra immagine (PNG, JPG o WEBP, quadrata) o tornare al gufo di serie.']],
                ],
            ],
            'amministratore' => [
                'titolo' => 'Amministratore e Ufficio didattico', 'icona' => 'fa-gear', 'colore' => '#475569',
                'a_chi' => 'Per chi configura il portale: moduli e iter, uffici e persone, utenti, backup.',
                'in_breve' => 'La «Scrivania» mostra ciò che aspetta te. I moduli delle pratiche si creano e si modificano dal pannello, senza toccare il codice; gli uffici decidono chi lavora ogni passo; il backup gira da solo e si può provare a ripristinare.',
                'sezioni' => [
                    ['titolo' => 'La scrivania', 'immagine' => 'adm_scrivania.png', 'didascalia' => 'Le cose da fare e i moduli a cui hai accesso.',
                     'passi' => ['Dopo l’accesso al pannello trovi «Cose da fare»: pratiche da assegnare, verbali da firmare, convenzioni, tutorato.', 'I moduli (Eventi, Formazione Scuola Lavoro, Didattica, Gestione del portale) si aprono dalle card.']],
                    ['titolo' => 'Come è fatto il pannello: «Cosa devo fare», «Altro» e «Scarica»', 'immagine' => 'adm_did_home.png', 'didascalia' => 'La prima schermata della Didattica: i numeri di quello che aspetta te, e sotto tutte le sezioni.',
                     'passi' => ['Ogni area del pannello si apre su <b>«Cosa devo fare»</b>: poche schede con un numero e un pulsante. Le schede <b>rosse</b> aspettano te, quelle <b>gialle</b> aspettano qualcun altro (non devi fare altro), quelle con <b>0</b> sono a posto.', 'Il pulsante grande di una scheda ti porta direttamente alla cosa da fare. Sotto le schede trovi l’elenco di <b>tutte le sezioni</b>, con una riga che dice a cosa servono (in Didattica anche <b>Tirocini</b>).', 'Le azioni che servono di rado (modificare, duplicare, archiviare, eliminare, stampare, scrivere a tutti) sono nel menu <b>«Altro»</b>. Il pulsante «Elimina» è sempre in fondo e in rosso.', 'Ogni elenco si scarica dal menu <b>«Scarica»</b> in <b>Excel, PDF o CSV</b>. Se hai spuntato alcune righe o filtrato l’elenco, il file contiene solo quelle.'],
                     'nota' => 'Il menu a sinistra non cambia: le voci sono sempre le stesse. «Cosa devo fare» è la prima voce di ogni modulo.'],
                    ['titolo' => 'Didattica: le pratiche e le sedute', 'immagine' => 'adm_did_pratica.png', 'didascalia' => 'Una pratica: in alto cosa fare adesso, poi l’iter. L’assegnazione a un’altra persona è in un riquadro che si apre solo quando serve.',
                     'passi' => ['Da «Cosa devo fare» apri le <b>pratiche da lavorare</b> o <b>da assegnare</b>: ogni pratica dice in alto <b>cosa fare adesso</b> e ha un solo pulsante per farlo.', 'Per passare la pratica a un’altra persona apri il riquadro «Passa la pratica a un’altra persona»: sceglie il passo, l’operatore e, se vuoi, una nota interna.', 'Una <b>seduta</b> ha sette passi (convocazione, presenze, cosa è stato detto, pratiche e decisioni, esiti agli studenti, verbale, firme): in alto vedi il <b>passo corrente</b> con il pulsante «Vai al passo».', 'Dalla seduta, «Scarica» dà il verbale in Word e l’elenco delle pratiche in Excel, PDF o CSV.']],
                    ['titolo' => 'Tutorato: le lettere di incarico', 'immagine' => 'adm_tutorato.png', 'didascalia' => 'Tutorato: lettere da inviare, da firmare, da protocollare e pagamenti.',
                     'passi' => ['«Cosa devo fare» mostra le lettere per punto dell’iter: <b>da inviare</b>, <b>aspettano lo studente</b>, <b>da firmare</b>, <b>da protocollare</b>, <b>da validare e pagare</b>.', 'Il percorso è lo stesso per tutti i bandi: vincitore, lettera, conferma dello studente con SPID/CIE, firma del docente, firma del Direttore, protocollo, registro e fine attività, UNILAV e pagamento.', 'Con l’<b>iter per Uniticket</b> in più c’è la presa di servizio da verificare prima di inviare la lettera, e a firme finite lettera e modello SCAFIS da allegare su Uniticket; poi il percorso è identico.']],
                    ['titolo' => 'Formazione Scuola Lavoro: le convenzioni con le scuole', 'immagine' => 'adm_fsl_home.png', 'didascalia' => 'Convenzioni con le scuole: da prendere in carico, da protocollare, dal Direttore, scuole senza convenzione.',
                     'passi' => ['La prima schermata mostra quattro schede: <b>da prendere in carico</b> (la scuola ha caricato il PDF firmato), <b>da protocollare</b> (ha firmato il Direttore), <b>dal Direttore per la firma</b> (non devi fare altro), <b>scuole senza convenzione</b>.', 'Apri la scheda di una scuola: vedi i <b>cinque passi</b> (la scuola compila, tu protocolli, il Direttore firma, tu registri, fatto) e un riquadro con l’<b>unica cosa da fare adesso</b>.', 'Il <b>registro</b> ha l’interruttore In vigore / Scadute, la ricerca e «Scarica»; le convenzioni in scadenza hanno il pulsante «Rinnova».', 'Nel menu «Altro»: registrare una convenzione già firmata fuori dal portale, ricordare a tutte le scuole di caricare il PDF, controllare le iscrizioni senza convenzione, i testi delle email.']],
                    ['titolo' => 'Eventi, iscritti e statistiche', 'immagine' => 'adm_ev_dashboard.png', 'didascalia' => 'La dashboard di un’area: iscrizioni da approvare, messaggi, attestati da controllare e turni in arrivo.',
                     'passi' => ['Nella dashboard dell’area le schede in alto dicono cosa fare: <b>iscrizioni da approvare</b>, <b>messaggi da leggere</b>, <b>attestati da controllare</b>, <b>turni dei prossimi 7 giorni</b>.', 'In «Eventi e turni» ogni evento ha il pulsante <b>Modifica</b> e il menu <b>Altro</b> (scheda pubblica, duplica, archivia, elimina); anche ogni turno ha Modifica e un menu (QR dell’aula, duplica, elimina). Le «Sezioni» per raggruppare gli eventi sono in un riquadro che si apre solo se serve.', 'In «Iscritti e presenze» ogni riga ha un pulsante principale (<b>Approva</b> se la richiesta aspetta te, altrimenti <b>Apri</b>) e un menu con ricevuta, messaggi, attestato, annulla ed elimina. In alto: «Aggiungi un iscritto», «Scanner», «Altro» (scrivi a tutti, badge, attestati) e «Scarica».']],
                    ['titolo' => 'Gestione del portale', 'immagine' => 'adm_portale_home.png', 'didascalia' => 'Gestione del portale: i controlli da guardare e tutte le sezioni.',
                     'passi' => ['La prima schermata mostra: <b>controlli del sito</b> da guardare, <b>email non partite</b> nell’ultima settimana, <b>persone non più in anagrafe</b> e <b>Direttore da indicare</b>.', 'In «Sistema» le impostazioni di invio (SMTP) sono in un riquadro chiuso: si aprono solo se cambia il server di posta.']],
                    ['titolo' => 'Moduli e iter delle pratiche', 'immagine' => 'adm_moduli.png', 'didascalia' => 'Moduli e documenti: le pratiche attive, i campi e l’iter di ciascuna.',
                     'passi' => ['In Didattica, «Moduli e documenti»: ogni pratica nasce inattiva. Aprila con «Anteprima», controlla campi e testi e attivala quando va bene.', 'Dalla procedura guidata a sette passi cambi campi, iter (chi la lavora e in che ordine), testo del verbale ed email. Con «Copia» parti da una pratica simile.', 'Gli uffici e le persone si indicano in «Ufficio e ricevimento»: l’ufficio protocollo, quelli dei corsi di studio, Internazionalizzazione, Ufficio attestati.', 'I certificati sono una sola pratica con tendina (iscrizione, laurea, rinuncia); la tesi unisce richiesta, Conservazione e Restauro e variazione.']],
                    ['titolo' => 'Il mio lavoro nell’area personale', 'passi' => ['Dopo l’accesso, nell’<b>area personale</b> trovi la scheda <b>«Il mio lavoro»</b>: una tessera per ogni cosa che gestisci (pratiche degli studenti, protocollo, sedute e verbali, convenzioni, tutorato, assistenza), con il <b>numero delle cose che aspettano</b>.', 'I pulsanti sotto la tessera sono <b>tutte le azioni</b> che puoi fare e aprono subito la vista giusta (per esempio «Da assegnare», «Assegnate a me», «Nuova seduta»). Se gestisci un’area, la sua tessera ha <b>iscritti e presenze, scanner, messaggi, sondaggi, statistiche</b> e, se puoi, «Nuovo evento» e «Nuovo progetto». Si lavora nella stessa pagina di sempre, con gli stessi permessi; in alto c’è il pulsante <b>Area personale</b> per tornare.', 'La scheda compare solo a chi ha almeno una cosa da gestire. In Gestione del portale → <b>Area personale</b> puoi spostarla, spegnerla o limitarla a un profilo.']],
                    ['titolo' => 'Riepilogo settimanale con l’agenda', 'passi' => ['In Gestione del portale → <b>Email e promemoria</b> trovi «Riepilogo settimanale con l’agenda», <b>spento</b> di partenza: lo accendi tu con un pulsante (e lo spegni quando vuoi).', 'Da acceso, l’email settimanale «Da fare per te» porta anche gli appuntamenti dei sette giorni a venire (eventi, aule, ricevimenti, scadenze) e arriva anche a chi ha solo qualcosa in agenda, studenti compresi, con il testo «La tua settimana». Ognuno può disiscriversi dal link in fondo; i testi si cambiano in «Email».'],
                     'nota' => 'Non cambia i promemoria al Direttore e agli uffici: quelli si sospendono dalla scheda «Promemoria al Direttore e agli uffici».'],
                    ['titolo' => 'Uffici e persone', 'passi' => ['In Gestione del portale → <b>Uffici e persone</b> crei gli uffici del Dipartimento (Direzione, protocollo, uffici dei corsi di studio, segreteria…) e di Ateneo (pagamenti…): una volta sola, poi si richiamano ovunque.', 'Le persone si scelgono <b>sempre dall’anagrafe di Ateneo</b> (non c’è l’inserimento a mano). Una persona può stare in più uffici.', 'Per gli uffici che lavorano le pratiche indichi anche i <b>compiti</b> (pratiche, sedute, ricevimento, bandi) e i corsi di studio seguiti: senza compiti la persona è nell’ufficio e riceve gli avvisi, ma non apre il pannello Didattica.', 'La <b>Direzione</b> (Direttore e vice direttore) e la segreteria di direzione sono uffici fissi: da lì si imposta chi firma e si attiva «Direttore assente».', 'Gli stessi uffici si scelgono nell’iter dei moduli, nel bando di tutorato (ufficio che paga), tra i responsabili di una risorsa e per le convenzioni FSL (ufficio convenzioni).'],
                     'nota' => 'Un ufficio che è nell’iter di un modulo, ha pratiche in corso, paga un bando o è responsabile di una risorsa non si può eliminare: il portale dice dove è usato.'],
                    ['titolo' => 'Cambiare il testo di un’email', 'passi' => ['In Gestione del portale → <b>Testi delle email</b> trovi <b>tutte</b> le email che il portale invia, divise per modulo (Didattica, Tutorato, Convenzioni, Risorse, Eventi e iscrizioni, Direzione e sistema). I moduli sono <b>schede</b> in alto (Tutorato, Didattica, Convenzioni, Risorse, Eventi e iscrizioni, Direzione e sistema): la scheda in cui eri resta aperta quando torni dall’editor. Per ogni email c’è scritto <b>quando parte</b> e <b>a chi arriva</b>; la ricerca in alto cerca in tutti i moduli. Dalle pagine dei moduli il pulsante «Testi delle email» apre l’elenco già limitato a quel modulo.', 'Apri un’email: cambi l’oggetto, il testo e (se c’è) la scritta del pulsante. I dati che cambiano da persona a persona (nome, bando, date…) si inseriscono con i <b>segnaposto</b> tra doppie graffe, per esempio <code>{{tutor}}</code>: clicca il segnaposto a destra per inserirlo dove si trova il cursore. Il testo si scrive semplice: una riga vuota separa i paragrafi, <code>**così**</code> è il grassetto, le righe che iniziano con <code>- </code> sono un elenco, quelle con <code>&gt; </code> una citazione evidenziata. Le email degli eventi si scrivono con l’editor e usano segnaposto a graffa singola, come <code>{NOME}</code>.', '<b>Anteprima</b> mostra l’email con dati d’esempio senza salvare; <b>Inviami una prova</b> la manda al tuo indirizzo; <b>Salva</b> la rende valida da subito; <b>Ripristina l’originale</b> torna al testo scritto dal portale. Ogni modifica resta nel registro attività con chi l’ha fatta.', 'Alcune email degli eventi (attestato, sondaggio) sono <b>facoltative</b>: hanno la spunta «Invia questa email» e senza la spunta non partono.'],
                     'nota' => 'Chi gestisce un modulo (Didattica, tutorato, convenzioni) cambia le email del proprio modulo; le altre le cambiano gli amministratori. Il link del pulsante e le parti preparate dal portale (tabelle, elenchi) non si modificano da qui.'],
                    ['titolo' => 'Prenotazioni e risorse', 'immagine' => 'adm_prenotazioni.png', 'didascalia' => 'Le prenotazioni dell’area, con gli stati e i filtri.',
                     'passi' => ['Ogni risorsa ha orari, durata dello slot, approvazione sì/no e, se vuoi, la ripetizione (settimanale, ogni due settimane, mensile).', 'Le liste d’attesa funzionano da sole: non c’è nulla da configurare. Il responsabile e il Direttore vedono le richieste ferme.']],
                    ['titolo' => 'Backup e ripristino', 'immagine' => 'adm_sistema.png', 'didascalia' => 'Sistema: email, backup e controlli notturni.',
                     'passi' => ['Ogni notte il portale esporta il database, comprime i file del sito (comprese le cartelle uploads con verbali, convenzioni e allegati) e li copia sul NAS. Una copia cifrata del solo database arriva per email agli indirizzi indicati.', 'Dopo ogni backup viene <b>verificato</b>: il file del database si rilegge per intero e lo ZIP dei file si riapre. Se qualcosa non torna ricevi un’email e lo vedi in «Sistema».', 'Una volta al mese conviene <b>provare il ripristino</b> (non tocca il portale): <code>php strumenti/ripristina_backup.php prova backup_DB_…sql.gz</code> importa il database in un database di prova e confronta tabelle e righe.', 'Per i file: <code>php strumenti/ripristina_backup.php file backup_SITO_…zip cartella_nuova</code> li estrae in una cartella a parte, da cui si copiano quelli che servono.', 'Il <b>ripristino vero</b> del database cancella e ricrea le tabelle: <code>… database backup_DB_…sql.gz --sovrascrivi-il-database-del-portale</code>. Si usa solo dopo aver provato il backup; poi si svuota la cartella cache e si apre il portale.'],
                     'nota' => 'Il backup completo dipende dalle variabili nel file .env: BACKUP_NAS_PATH (cartella del NAS), BACKUP_EMAIL e BACKUP_PASSWORD (almeno 12 caratteri) per la copia cifrata del database.'],
                ],
            ],
        ];
    }
}
